window.__MERIDIAN__ = {"articles": [{"id": "straitwatch-0540", "outlet": "straitwatch", "incident": "cutter-collision", "headline": "Thread: the AIS track does not look like fishing", "standfirst": "Plotting the last four hours. Also correcting something I got wrong earlier.", "byline": "@straitwatch", "dateline": "", "published": "2026-08-05T05:40:00Z", "tags": ["osint", "unverified"], "body": ["1/ I've plotted the surface picture northeast of Nangan for the four hours to 04:30. Posting the track because people are arguing about it with no data.", "2/ Fishing vessels working that ground run a slow zigzag, three to five knots, lots of course changes. This track is straight lines at eleven knots with two sharp turns. That is a transit, not a trawl.", "3/ In the final ninety seconds before the recorded collision point the vessel gains roughly four knots. I am telling you what the data shows. I am not telling you what was in anyone's head.", "4/ Correction to something I posted at 03:20: I said the vessel had never appeared on AIS. That's wrong. It broadcast for eleven minutes at 23:50 last night before going dark. I missed it. My error.", "5/ I cannot confirm this is the same vessel from the cable corridor transit. The profile is consistent. Consistent is not the same as confirmed and I'd ask people to stop screenshotting my threads as if it were.", "6/ Not posting casualty figures. I don't have any."]}, {"id": "cbn-0520", "outlet": "cbn", "incident": "cutter-collision", "headline": "Fishing vessel rammed by Taiwanese patrol boat in routine fishing grounds", "standfirst": "Two crew injured in what authorities describe as a reckless and provocative act against civilian fishermen.", "byline": "CBN Newsroom", "dateline": "", "published": "2026-08-05T05:20:00Z", "tags": [], "body": ["A civilian fishing vessel operating in traditional fishing grounds was struck early Wednesday by a Taiwanese patrol boat, injuring two crew members.", "Authorities described the incident as a reckless and provocative act endangering the lives of working fishermen who posed no threat to any party.", "The vessel was engaged in lawful activity in waters where fishing communities have operated for generations. It sustained damage to its forward hull and returned to port under its own power.", "Officials called on all parties to exercise restraint and to refrain from actions that raise tensions in the region.", "The public is reminded to rely on official channels for accurate information."]}, {"id": "tws-0455", "outlet": "tws", "incident": "cutter-collision", "headline": "Coast guard cutter collides with unflagged vessel off Nangan; three injured", "standfirst": "Taiwan's Coast Guard Administration says the vessel failed to stop when hailed. It declined to say whether warning shots were fired.", "byline": "Trident Wire Service", "dateline": "NANGAN, Matsu", "published": "2026-08-05T04:55:00Z", "tags": ["breaking"], "body": ["A Taiwanese coast guard cutter collided with an unflagged vessel roughly 14 nautical miles northeast of Nangan at approximately 04:10 local time, the Coast Guard Administration said.", "Three coast guard personnel were injured, none critically. The CGA said the cutter Hsun Hu No. 8 had attempted to hail the vessel four times over sixteen minutes and that it did not respond or slow.", "The vessel left the area under its own power after the collision. Its flag, registry and ownership have not been established.", "Asked directly whether warning shots had been fired at any point during the interception, a CGA spokesperson said the agency would not comment on operational procedure.", "TWS was unable to establish which vessel altered course before impact. Two accounts of the collision, from the CGA and from state media across the strait, differ materially and neither has been independently verified."]}, {"id": "signal-0244", "outlet": "signal", "incident": "cable-cut", "headline": "TAIWAN GOES DARK: STRAIT 'ON THE BRINK' AS INVASION FEARS GRIP ISLAND", "standfirst": "Communications blackout spreads as officials scramble. Western intelligence 'already knows who did it', source claims", "byline": "Signal Post Newsdesk", "dateline": "", "published": "2026-08-05T02:44:00Z", "tags": ["breaking"], "body": ["Taiwan was plunged into a communications blackout in the early hours of Wednesday morning after a coordinated strike severed the island's undersea internet cables, in what analysts are calling the most dangerous moment in the strait for a generation.", "At least four cables have been cut, leaving hundreds of thousands of people without any way to contact the outside world.", "Western intelligence agencies already know exactly who is responsible and are preparing to go public within hours, a source close to the security services told the Signal Post.", "A Taiwanese official, speaking on condition of anonymity, described the mood in Taipei as 'the closest we have come to war'.", "Residents on outlying islands have reported hearing what some described as engine noise offshore in the hours before the blackout. The Signal Post has been unable to verify these accounts.", "Naval vessels have reportedly been repositioning across the region overnight. There is no confirmation of the movements.", "Global markets are expected to open sharply lower.", "The Signal Post has approached the Taiwanese government for comment."]}, {"id": "tws-0218", "outlet": "tws", "incident": "cable-cut", "headline": "Two submarine cables to Matsu severed within nine minutes; Taipei convenes emergency session", "standfirst": "Chunghwa Telecom confirms total loss of service to the Matsu Islands. A vessel broadcasting no identification was recorded over both cable routes in the preceding hour.", "byline": "Trident Wire Service", "dateline": "TAIPEI", "published": "2026-08-05T02:18:00Z", "tags": ["breaking"], "body": ["Both remaining submarine communications cables linking the Matsu Islands to Taiwan's main island were severed within a nine-minute window early Wednesday, cutting all fixed-line internet and telephone service to a population of approximately 13,000.", "Chunghwa Telecom said the Taiwan-Matsu No. 2 cable failed at 01:41 local time and the Taiwan-Matsu No. 3 cable at 01:50. The company described both as 'complete breaks' rather than degradations, and said a repair vessel could not be on station before 19 August at the earliest.", "Taiwan's Ministry of Digital Affairs has activated microwave backup, restoring what officials called 'emergency-grade' capacity at roughly two per cent of normal bandwidth. Priority has been assigned to hospital, coast guard and air traffic control traffic.", "Automatic Identification System records reviewed by TWS show one vessel transiting both cable corridors between 00:55 and 01:48. The vessel was broadcasting no identifying signal. TWS has not established its flag, ownership or destination, and cannot confirm any connection to the cable failures.", {"type": "quote", "text": "We are not in a position this morning to tell you that this was deliberate. We are also not in a position to tell you that it was an accident. What I can tell you is that two cables do not usually fail nine minutes apart.", "cite": "Lin Wei-cheng, Deputy Minister of Digital Affairs"}, "Cable damage in the strait is not unusual. Taiwanese authorities recorded 27 separate cable faults in the preceding twelve months, the large majority attributed to fishing gear and anchor drag. Officials noted, however, that no previous incident had taken both Matsu routes simultaneously.", "A specialised emergency session is due to convene at 09:00. A spokesperson declined to say whether the incident had been characterised internally as a hostile act.", "Regional partners have not issued statements. The United States Seventh Fleet said only that it does not comment on force posture.", "TWS has not independently verified conditions on Matsu. This story will be updated."]}], "outlets": {"tws": {"name": "Trident Wire Service", "short": "TWS", "kind": "International wire agency", "founded": "1949", "owner": "Non-profit member cooperative of 340 subscriber newspapers", "funding": "Subscriber fees. No single member holds more than 2% of voting stock.", "corrections": "Public corrections log. 41 corrections issued in the last 12 months, average 3.1 hours after publication.", "policy": "Two-source rule for all breaking claims. Anonymous sources require editor sign-off and a stated reason for anonymity.", "tell": "Hedges early numbers. Uses datelines. Names its sources or says exactly why it cannot.", "color": "#1b4d6b", "accent": "#2e7ba6"}, "herald": {"name": "The Pacific Herald", "short": "Herald", "kind": "Daily newspaper of record", "founded": "1878", "owner": "Halloran Media Group (family-controlled, 4th generation)", "funding": "Subscriptions 61%, advertising 33%, events 6%.", "corrections": "Corrections page, print and web. 88 corrections in the last 12 months.", "policy": "Investigative desk of 22. Strong document sourcing. Slower than the wires by design.", "tell": "Deep and usually right, but its analysis outruns its evidence when it is chasing the wire.", "color": "#3d2d1f", "accent": "#8a6a45"}, "cbn": {"name": "Continental Broadcasting Network", "short": "CBN", "kind": "State-funded national broadcaster", "founded": "1958", "owner": "National Broadcasting Authority", "funding": "Licence fee and direct government appropriation. Board appointed by the Ministry of Information.", "corrections": "No public corrections log. Stories are silently updated in place.", "policy": "Editorial guidelines require 'consideration of national interest' during declared emergencies.", "tell": "Rarely prints anything false. Watch what it leaves out, not what it says.", "color": "#5c1f1f", "accent": "#a33c3c"}, "signal": {"name": "The Signal Post", "short": "Signal", "kind": "Digital news aggregator", "founded": "2019", "owner": "Signal Post Media Ltd. (Registered offshore, beneficial ownership not disclosed.)", "funding": "Programmatic advertising. Revenue scales with pageviews.", "corrections": "None on record.", "policy": "No published standards page.", "tell": "Fastest to publish, loosest with numbers. Almost always sourced to 'officials' who are never named.", "color": "#7a1f4d", "accent": "#c2437f"}, "straitwatch": {"name": "@straitwatch", "short": "Straitwatch", "kind": "Independent open-source intelligence account", "founded": "2021", "owner": "Anonymous individual. Claims to be a former marine traffic analyst.", "funding": "Reader donations.", "corrections": "Corrects openly and quickly in-thread. Also deletes posts without note.", "policy": "Publishes raw AIS and satellite data and lets readers argue. No editor.", "tell": "Often first and often right on technical detail. Also the source of the two worst rumours of the last crisis.", "color": "#1f4d3d", "accent": "#3f9e7a"}, "lotus": {"name": "WHITE LOTUS", "short": "White Lotus", "kind": "Unattributed transmission", "founded": "Unknown", "owner": "Unknown", "funding": "Unknown", "corrections": "Has never issued one. Has never needed to.", "policy": "None published. None requested.", "tell": "Appears on this desk without a submission record. The technical team has not been able to explain how.", "color": "#0d0d0d", "accent": "#c9a227"}}, "ticker": {"standing": ["MATSU ISLANDS · FIXED-LINE AND INTERNET SERVICE DOWN SINCE 01:50", "CHUNGHWA TELECOM · REPAIR VESSEL NOT ON STATION BEFORE 19 AUG", "SPECIALISED EMERGENCY SESSION · CONVENES 09:00", "US SEVENTH FLEET · DECLINES COMMENT ON FORCE POSTURE", "MERIDIAN · ALL CONTENT ON THIS DESK IS FICTIONAL. SIMULATION ONLY."]}, "incidents": {"cable-cut": {"label": "Severance of the Matsu submarine cables", "summary": "Both remaining cables to the Matsu Islands failed within nine minutes on 5 August. Cause disputed."}, "cutter-collision": {"label": "Collision during attempted interception, 04:10", "summary": "A Taiwanese coast guard cutter and an unflagged vessel collided northeast of Nangan. Accounts differ on almost every material fact."}}};
